class Solution {
    public int mySqrt(int x) {
        int left = 0, right = x;
        while (right >= left) {
            int middle = (left + right) / 2;
            long square = (long) middle * middle;
            if (square == x) return middle;
            else if (square > x) right = middle - 1;
            else left = middle + 1;
        }
        return right;
    }
}

